import React from 'react';
import { ScrollView, View, Text, StyleSheet } from 'react-native';

const ScrollViewExample = () => {
  return (
    <View style={styles.container}>
      <Text style={styles.header}>Vertical Scroll</Text>
      <ScrollView style={styles.scrollView}>
        {[1, 2, 3, 4, 5, 6, 7, 8].map((item) => (
            <View key={item} style={styles.box}>
                <Text style={styles.text}>Box {item}</Text>
            </View>
        ))}
      </ScrollView>

      <Text style={styles.header}>Horizontal Scroll</Text>
      <ScrollView 
        horizontal 
        showsHorizontalScrollIndicator={false}
        style={styles.horizontalScroll}
      >
        {[1, 2, 3, 4, 5].map((item) => (
            <View key={item} style={styles.card}>
                <Text style={styles.text}>Card {item}</Text>
            </View>
        ))}
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, paddingTop: 40, paddingHorizontal: 10 },
  header: { fontSize: 20, fontWeight: 'bold', marginVertical: 10 },
  scrollView: { height: 200, backgroundColor: '#f0f0f0', marginBottom: 20 },
  horizontalScroll: { flexGrow: 0 },
  box: {
    height: 60,
    backgroundColor: '#3498db',
    margin: 10,
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 8
  },
  card: {
    width: 120,
    height: 120,
    backgroundColor: '#e74c3c',
    marginRight: 15,
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 12
  },
  text: { color: 'white', fontWeight: 'bold' }
});

export default ScrollViewExample;
